/* PDF rasterization for derived OCR only. Runs inside a dedicated denied-network worker. */
(function(root){'use strict';
const MAX_BYTES=5242880,MAX_PAGES=200,MAX_PIXELS=8000000,MAX_EDGE=4096;
class CanvasFactory{
 create(width,height){if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>MAX_EDGE||height>MAX_EDGE||width*height>MAX_PIXELS)throw Error('PDF image exceeds the OCR canvas budget.');const canvas=new OffscreenCanvas(width,height);return{canvas,context:canvas.getContext('2d',{willReadFrequently:true})};}
 reset(target,width,height){if(!target?.canvas||!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>MAX_EDGE||height>MAX_EDGE||width*height>MAX_PIXELS)throw Error('PDF image exceeds the OCR canvas budget.');target.canvas.width=width;target.canvas.height=height;}
 destroy(target){if(target?.canvas){target.canvas.width=1;target.canvas.height=1;}target.canvas=null;target.context=null;}
}
class NoFilters{addFilter(){throw Error('PDF transfer filters are unsupported for OCR rendering.');}addHCMFilter(){throw Error('PDF color filters are unsupported for OCR rendering.');}addAlphaFilter(){throw Error('PDF alpha filters are unsupported for OCR rendering.');}addLuminosityFilter(){throw Error('PDF luminosity filters are unsupported for OCR rendering.');}addLuminosityAlphaFilter(){throw Error('PDF luminosity filters are unsupported for OCR rendering.');}addHighlightHCMFilter(){throw Error('PDF highlight filters are unsupported for OCR rendering.');}destroy(){}}
class NoExternalData{async fetch(){throw Error('External PDF rendering data is disabled.');}}
async function documentTask(bytes){if(!(bytes instanceof Uint8Array)||bytes.length>MAX_BYTES||new TextDecoder('ascii').decode(bytes.subarray(0,5))!=='%PDF-')throw Error('PDF OCR rendering needs a valid PDF no larger than 5 MB.');if(typeof OffscreenCanvas!=='function'||typeof DOMMatrix!=='function')throw Error('PDF OCR rendering needs isolated OffscreenCanvas and DOMMatrix support.');const task=root.pdfjsLib.getDocument({data:bytes.slice(),isEvalSupported:false,useWorkerFetch:false,useWasm:false,useSystemFonts:false,disableFontFace:true,enableXfa:false,isOffscreenCanvasSupported:true,isImageDecoderSupported:false,disableAutoFetch:true,disableStream:true,disableRange:true,stopAtErrors:true,maxImageSize:MAX_PIXELS,canvasMaxAreaInBytes:MAX_PIXELS*4,CanvasFactory,FilterFactory:NoFilters,BinaryDataFactory:NoExternalData,verbosity:0});return task;}
root.PBGCPdfOcrRender=async function(request){let task;try{
 task=await documentTask(new Uint8Array(request.bytes));const doc=await task.promise;if(!Number.isInteger(doc.numPages)||doc.numPages<1||doc.numPages>MAX_PAGES)throw Error('PDF exceeds the 200-page OCR inspection limit.');if(request.action==='inspect')return{pages:doc.numPages};
 const pageNumber=request.pageNumber,scale=request.scale,maxPixels=request.maxPixels;if(!Number.isInteger(pageNumber)||pageNumber<1||pageNumber>doc.numPages||typeof scale!=='number'||!Number.isFinite(scale)||scale<0.25||scale>4||!Number.isInteger(maxPixels)||maxPixels<1||maxPixels>MAX_PIXELS)throw Error('Invalid PDF OCR render options.');const page=await doc.getPage(pageNumber);try{const viewport=page.getViewport({scale}),width=Math.ceil(viewport.width),height=Math.ceil(viewport.height);if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>MAX_EDGE||height>MAX_EDGE||width*height>maxPixels)throw Error('PDF page exceeds the OCR pixel or edge budget at this resolution.');if(!page.view.every(Number.isFinite)||!viewport.transform.every(Number.isFinite))throw Error('PDF page has invalid OCR geometry.');const surface=new CanvasFactory().create(width,height);try{await page.render({canvasContext:surface.context,viewport,background:'#ffffff',annotationMode:root.pdfjsLib.AnnotationMode.DISABLE,intent:'display'}).promise;const image=surface.context.getImageData(0,0,width,height);return{width,height,data:image.data,pageView:page.view.slice(),rotation:page.rotate,transform:viewport.transform.slice()};}finally{new CanvasFactory().destroy(surface);}}finally{page.cleanup();}
 }catch(error){if(error?.name==='PasswordException')throw Error('Encrypted PDF OCR requires a password and is unsupported.');throw error;}finally{if(task)await task.destroy().catch(()=>{});}};
})(globalThis);
